  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "The inclusion criteria were: (1) Conformed to research questions, i.e., studies that estimated the reinfection rate of SARS-CoV-2 or we could calculate it based on the data provided in the paper; (2) The study design included cohort study, case-control study, and descriptive study; (3) The study fited our working definition of SARS-CoV-2 reinfection. ... reinfection working definition in this study was based on a positive laboratory result at least 90 days after laboratory confirmation of primary infection(laboratory testing methods include reverse transcription-polymerase chain reaction or rapid antigen test, also called Lateral Flow Devices, and so on) ... The exclusion criteria were: (1) The sample size was less than 20; ... (4) Original research.",
      "reason": "Eligibility study characteristics (research question fit, eligible study designs, and reinfection follow-up interval/working definition) are specified, but settings and explicit follow-up requirements beyond the reinfection interval are not fully described in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "To avoid language bias, the search was not limited to any language. We conducted preliminary screening based on the English title and English abstract provided by nonEnglish articles. Further, in the screening process, if the included article was neither in English nor in Chinese and did not provide an English abstract or full text, we used an online translator (Google Translate) for translation. There were no non-English articles in the final articles included in this study.",
      "reason": "Language criteria and handling are described, but dissemination year and publication/report status criteria (e.g., dates, published vs. preprints) are not specified in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not distinguish exclusions due to outcomes not measured versus outcomes results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Subgroup analyses were performed by meta-regression to fit stratified rates of reinfection based on variables such as variant and country, and we also used spline regression to fit time-varying reinfection rates that did not account for heterogeneity.",
      "reason": "The synthesis grouping variables used in subgroup/meta-regression (e.g., variant and country) and the time-varying grouping approach (time-varying reinfection rates via spline regression/meta-regression) are specified for the syntheses."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "To avoid language bias, the search was not limited to any language.",
      "reason": "A rationale is provided for a notable restriction/approach (no language limitation) to avoid language bias."
    }
  ],
  "confidence": 78
}

